    ParseLogLine(L"2026.10.10 12:00:05 Log - [Behaviour] OnPlayerJoined 名前だけ",e);timeline.Add(e);timeline.Add(e);require(timeline.At(local+6000).status==L"partial"&&timeline.At(local+6000).members.size()==3,"Stage3 unknown IDs remain separate partial observations");
    ParseLogLine(L"2026.10.10 12:00:07 Log - [Behaviour] Joining "+world+L":other",e);timeline.Add(e);require(timeline.At(local+8000).members.empty(),"Stage3 instance change resets members in same world");
    auto file=folder/L"output_log_test.txt";auto write=[&](const std::string& data,bool append){std::ofstream out(file,std::ios::binary|(append?std::ios::app:std::ios::trunc));out<<data;};
    write(winrt::to_string(L"2026.10.10 12:00:00 Log - [Behaviour] Joining "+world+L":123\n2026.10.10 12:00:01 Log - [Behaviour] OnPlayerJoined A ("+idA+L")\n2026.10.10 12:00:02 Log - [Behaviour] OnPlayerJoined B ("+idB+L")"),false);
