    auto photo=folder/L"VRChat_2026-10-10_12-00-04.100_320x160.png";write(winrt::to_string(L"2026.10.10 12:00:04 Log - [VRC Camera] Took screenshot to: "+photo.wstring()+L"\n"),true);log.Read(file);auto decision=Correlate(photo.wstring(),L"",world,local+5000,log);require(decision.ready&&decision.record.timeSource==L"filename"&&decision.record.members.size()==2,"Stage3 correlates photo filename and historical session");
    require(!Correlate(photo.wstring(),L"2026-10-10T12:01:00",world,local+5000,log).ready,"Stage3 holds inconsistent capture time");require(!Correlate(photo.wstring(),L"",L"wrld_other",local+5000,log).ready,"Stage3 holds contradictory world");require(!Correlate((folder/L"manual.png").wstring(),L"",world,local+5000,log).ready,"Stage3 holds manual photo without matching capture log");
    fs::copy_file(root/L"xmp-日本語.png",photo,fs::copy_options::overwrite_existing);auto fingerprint=MetadataFingerprint(photo.wstring());auto old=InspectEditable(photo.wstring());MetadataEdit edit;edit.stage3Xml=RecordXml(decision.record);auto output=folder/L"recorded.png";fs::remove(output);SaveMetadataCopy(photo.wstring(),output.wstring(),fingerprint,edit);
    auto reread=InspectEditable(output.wstring());require(reread.values==old.values&&MetadataFingerprint(photo.wstring())==fingerprint,"Stage3 output copy preserves original and manual metadata");auto summary=ReadPhotoSummary(output.wstring());require(summary.xmpDetail.find(L"InstanceMembers")!=std::wstring::npos&&summary.xmpDetail.find(L"not-observed")!=std::wstring::npos,"Stage3 rereads structured members and not-observed candidate state");
    require(summary.values[9]==L"A\r\nB"&&summary.values[10]==L"未観測","v0.4.1 summary displays members and unobserved candidates");
    XmpFields displayFields;std::wstring displayError;auto displayXml=RecordXml(decision.record);size_t prefixPos=0;while((prefixPos=displayXml.find("kpe:",prefixPos))!=std::string::npos){displayXml.replace(prefixPos,4,"alt:");prefixPos+=4;}auto namespacePos=displayXml.find("xmlns:kpe=");if(namespacePos!=std::string::npos)displayXml.replace(namespacePos,10,"xmlns:alt=");
    require(ParseXmp(displayXml,displayFields,displayError)&&displayFields.members==L"A\r\nB","v0.4.1 participant parsing resolves namespace URI independently of prefix");
    Record namesRecord=decision.record;namesRecord.memberStatus=L"partial";namesRecord.candidateStatus=L"observed";namesRecord.members={{L"同名 & 名前",idA},{L"同名 & 名前",idB}};
    auto namesXml=RecordXml(namesRecord);auto candidatesAt=namesXml.find("<kpe:ModelCandidates>");auto candidatesEnd=namesXml.find("</kpe:ModelCandidates>",candidatesAt)+std::string("</kpe:ModelCandidates>").size();namesXml.replace(candidatesAt,candidatesEnd-candidatesAt,"<kpe:ModelCandidates><rdf:Seq><rdf:li rdf:parseType='Resource'><kpe:DisplayName>候補 &amp; 名前</kpe:DisplayName><kpe:UserId>candidate-id</kpe:UserId></rdf:li></rdf:Seq></kpe:ModelCandidates>");
    MetadataEdit namesEdit;namesEdit.stage3Xml=namesXml;auto namesOutput=folder/L"display-names.png";fs::remove(namesOutput);auto namesSource=root/L"writer-alpha.png";SaveMetadataCopy(namesSource.wstring(),namesOutput.wstring(),MetadataFingerprint(namesSource.wstring()),namesEdit);auto namesSummary=ReadPhotoSummary(namesOutput.wstring());
    require(namesSummary.values[9]==L"部分的な記録\r\n同名 & 名前\r\n同名 & 名前"&&namesSummary.values[10]==L"候補 & 名前"&&namesSummary.values[7].empty(),"v0.4.1 structured candidate display preserves duplicate names and manual model separation");
    auto noMatchRecord=decision.record;noMatchRecord.candidateStatus=L"no-match";MetadataEdit noMatchEdit;noMatchEdit.stage3Xml=RecordXml(noMatchRecord);auto noMatchOutput=folder/L"display-no-match.png";fs::remove(noMatchOutput);SaveMetadataCopy(namesSource.wstring(),noMatchOutput.wstring(),MetadataFingerprint(namesSource.wstring()),noMatchEdit);require(ReadPhotoSummary(noMatchOutput.wstring()).values[10]==L"候補なし","v0.4.1 no-match display differs from unobserved");
    auto malformed=namesXml;auto arrayStart=malformed.find("<kpe:InstanceMembers>");auto arrayEnd=malformed.find("</kpe:InstanceMembers>",arrayStart)+std::string("</kpe:InstanceMembers>").size();malformed.replace(arrayStart,arrayEnd-arrayStart,"<kpe:InstanceMembers>bad-array</kpe:InstanceMembers>");require(ParseXmp(malformed,displayFields,displayError)&&displayFields.memberStatus==L"unknown"&&displayFields.members.empty(),"v0.4.1 malformed participant array is unknown rather than empty membership");
    auto second=folder/L"duplicate.png";fs::remove(second);bool rejected=false;try{SaveMetadataCopy(output.wstring(),second.wstring(),reread.fingerprint,edit);}catch(...){rejected=true;}require(rejected&&!fs::exists(second),"Stage3 automatic reprocessing preserves existing record");
    edit={};edit.actions[4]=EditAction::Set;edit.values[4]=L"手動確定";auto confirmed=folder/L"confirmed.png";fs::remove(confirmed);SaveMetadataCopy(output.wstring(),confirmed.wstring(),reread.fingerprint,edit);require(ReadPhotoSummary(confirmed.wstring()).xmpDetail.find(L"InstanceMembers")!=std::wstring::npos,"Stage2 manual subject edit preserves Stage3 automatic record");
    // Candidate editing retains per-person identity and observational data, including Extended XMP.
    {
        auto record=namesRecord;record.candidates={};
        Candidate candidate;candidate.person=record.members[0];candidate.raw=L"OCR raw evidence";candidate.method=L"normalized-exact";candidate.count=3;record.candidates.push_back(candidate);
        Candidate orphan=candidate;orphan.person={L"同室者にいない候補",L"usr_orphan"};record.candidates.push_back(orphan);
        auto xml=RecordXml(record,true);auto at=xml.find("</kpe:CaptureRecord>");xml.insert(at,"<kpe:Unknown>"+std::string(70000,'x')+"</kpe:Unknown>");
        for(auto name:{L"writer-alpha.png",L"sample.jpg",L"webp-lossy.webp"}){
            auto source=root/name;auto original=MetadataFingerprint(source.wstring());auto recorded=folder/(std::wstring(L"v0414-record-")+name);fs::remove(recorded);MetadataEdit initial;initial.stage3Xml=xml;SaveMetadataCopy(source.wstring(),recorded.wstring(),original,initial);
            auto snapshot=InspectEditable(recorded.wstring());require(snapshot.candidatesEditable&&snapshot.members.size()==2&&snapshot.candidates.size()==2&&snapshot.members[0].name==snapshot.members[1].name&&snapshot.members[0].id!=snapshot.members[1].id,"v0.4.14 structured people preserve same-name identities");
            MetadataEdit change;change.editCandidates=true;change.candidates={snapshot.candidates[0],snapshot.candidates[1],snapshot.members[1]};change.additionalCandidates=L"手入力 & <名前>\r\n手入力 & <名前>";
            auto target=folder/(std::wstring(L"v0414-edit-")+name);fs::remove(target);SaveMetadataCopy(recorded.wstring(),target.wstring(),snapshot.fingerprint,change);auto actual=InspectEditable(target.wstring());auto summary=ReadPhotoSummary(target.wstring());
            require(actual.candidates.size()==4&&actual.candidates[0].id==idA&&actual.candidates[1].id==L"usr_orphan"&&actual.candidates[2].id==idB&&actual.candidates[3].name==L"手入力 & <名前>"&&actual.candidates[3].id.empty(),"v0.4.14 PNG/JPEG/WebP selection and escaped manual names round trip");
            require(summary.xmpDetail.find(L"OCR raw evidence")!=std::wstring::npos&&summary.xmpDetail.find(L"normalized-exact")!=std::wstring::npos&&summary.xmpDetail.find(L"manual-selection")!=std::wstring::npos&&summary.xmpDetail.find(std::wstring(100,L'x'))!=std::wstring::npos&&actual.values==snapshot.values&&actual.members[0].id==snapshot.members[0].id&&MetadataFingerprint(source.wstring())==original,"v0.4.14 keeps OCR evidence, unknown XML, members, manual model and original pixels");
            MetadataEdit remove;remove.editCandidates=true;auto cleared=folder/(std::wstring(L"v0414-clear-")+name);fs::remove(cleared);SaveMetadataCopy(target.wstring(),cleared.wstring(),actual.fingerprint,remove);require(InspectEditable(cleared.wstring()).candidates.empty()&&ReadPhotoSummary(cleared.wstring()).values[10]==L"候補なし","v0.4.14 unchecking all clears only candidates");
            change.candidates[0].id=L"wrong-id";auto invalid=folder/(std::wstring(L"v0414-invalid-")+name);fs::remove(invalid);bool rejected=false;try{SaveMetadataCopy(recorded.wstring(),invalid.wstring(),snapshot.fingerprint,change);}catch(...){rejected=true;}require(rejected&&!fs::exists(invalid),"v0.4.14 stale person selection rejected before output");
        }
        {
            auto source=folder/L"v0414-overwrite.png";fs::copy_file(folder/L"v0414-record-writer-alpha.png",source,fs::copy_options::overwrite_existing);auto snapshot=InspectEditable(source.wstring());auto ledger=folder/L"v0414-backups.json";
            MetadataEdit change;change.editCandidates=true;change.candidates={snapshot.members[1]};SaveMetadataOverwrite(source.wstring(),snapshot.fingerprint,change,true,1000,ledger);
            auto records=ReadBackupLedger(ledger);require(InspectEditable(source.wstring()).candidates.size()==1&&InspectEditable(source.wstring()).candidates[0].id==idB&&std::any_of(records.begin(),records.end(),[&](auto& r){return r.fingerprint==snapshot.fingerprint&&MetadataFingerprint(r.path)==snapshot.fingerprint;}),"v0.4.14 candidate overwrite creates verified AB backup of original");
        }
        for(auto name:{L"writer-alpha.png",L"xmp-日本語.png",L"xmp-日本語.jpg"}){auto source=root/name;auto target=folder/(std::wstring(L"v0414-manual-only-")+name);fs::remove(target);MetadataEdit manual;manual.editCandidates=true;manual.additionalCandidates=L"手入力だけ";SaveMetadataCopy(source.wstring(),target.wstring(),MetadataFingerprint(source.wstring()),manual);auto actual=InspectEditable(target.wstring());require(actual.members.empty()&&actual.candidates.size()==1&&actual.candidates[0].name==L"手入力だけ"&&actual.values==InspectEditable(source.wstring()).values,"v0.4.14 manual candidates supported without automatic record and with alternate RDF prefix");}
    }
    require(SeparateFolders(folder,root/L"stage3-output")&&!SeparateFolders(folder,folder/L"output")&&!SeparateFolders(folder,folder),"Stage3 prevents nested output and feedback loops");
    {
        auto shotTime=Now()/1000*1000;ULARGE_INTEGER stamp{};stamp.QuadPart=shotTime*10000;FILETIME time{stamp.LowPart,stamp.HighPart};SYSTEMTIME utc{},localTime{};FileTimeToSystemTime(&time,&utc);SystemTimeToTzSpecificLocalTime(nullptr,&utc,&localTime);wchar_t name[128]{};swprintf_s(name,L"VRChat_%04u-%02u-%02u_%02u-%02u-%02u.000_640x240.png",localTime.wYear,localTime.wMonth,localTime.wDay,localTime.wHour,localTime.wMinute,localTime.wSecond);auto shot=folder/name;fs::copy_file(root/L"writer-alpha.png",shot,fs::copy_options::overwrite_existing);auto h=CreateFileW(shot.c_str(),FILE_WRITE_ATTRIBUTES,FILE_SHARE_READ|FILE_SHARE_WRITE|FILE_SHARE_DELETE,nullptr,OPEN_EXISTING,0,nullptr);require(h!=INVALID_HANDLE_VALUE&&SetFileTime(h,nullptr,nullptr,&time),"F12 fixture mtime");CloseHandle(h);
        LogMonitor steam;Event room;room.kind=Kind::Room;room.time=shotTime-10000;room.instance=L"steam-instance";room.world=L"wrld_test";steam.timeline.Add(room);Event person=room;person.kind=Kind::Join;person.time=shotTime-9000;person.person={L"SteamModel",L"usr_steam"};steam.timeline.Add(person);
        auto inferred=CorrelateSteam(shot.wstring(),shotTime+1000,steam);require(inferred.ready&&inferred.record.members.size()==1&&inferred.record.timeSource==L"screenshot-filename"&&inferred.record.timeStatus==L"estimated","v0.4.5 same-format F12 filename date and participants");require(!CorrelateSteam(shot.wstring(),shotTime+16000,steam).ready,"v0.4.5 F12 stale detection held");Event boundary=person;boundary.time=shotTime;boundary.kind=Kind::Leave;steam.timeline.Add(boundary);require(!CorrelateSteam(shot.wstring(),shotTime+1000,steam).ready,"v0.4.5 F12 membership boundary held");
        stamp.QuadPart=(shotTime-10000)*10000;time={stamp.LowPart,stamp.HighPart};h=CreateFileW(shot.c_str(),FILE_WRITE_ATTRIBUTES,FILE_SHARE_READ|FILE_SHARE_WRITE|FILE_SHARE_DELETE,nullptr,OPEN_EXISTING,0,nullptr);SetFileTime(h,nullptr,nullptr,&time);CloseHandle(h);require(!CorrelateSteam(shot.wstring(),shotTime+1000,steam).ready,"v0.4.5 F12 filename and mtime conflict held");
    }
